"import os
import json
import sys
import re

def clean_user_content(content):
    if not content:
        return ""
    # Extract content between <USER_REQUEST> and </USER_REQUEST> if present
    match = re.search(r"<USER_REQUEST>(.*?)</USER_REQUEST>", content, re.DOTALL)
    if match:
        return match.group(1).strip()
    return content.strip()

def export_to_markdown(conv_id, output_path):
    brain_dir = r"C:\Users\molis\.gemini\antigravity\brain"
    transcript_path = os.path.join(brain_dir, conv_id, ".system_generated", "logs", "transcript.jsonl")

    if not os.path.exists(transcript_path):
        print(f"Error: Transcript not found at {transcript_path}")
        return False

    try:
        with open(transcript_path, "r", encoding="utf-8") as f, open(output_path, "w", encoding="utf-8") as out:
            out.write(f"# Histórico da Conversa: {conv_id}\n\n")

            for line in f:
                try:
                    data = json.loads(line)
                    t = data.get("type")
                    content = data.get("content")

                    if t == "USER_INPUT" and content:
                        cleaned = clean_user_content(content)
                        out.write(f"## 👤 Usuário\n\n{cleaned}\n\n---\n\n")
                    elif t == "PLANNER_RESPONSE" and content:
                        out.write(f"## 🤖 Assistente (Antigravity)\n\n{content}\n\n---\n\n")
                except Exception:
                    pass
        print(f"Success: Exported to {output_path}")
        return True
    except Exception as e:
        print(f"Error during export: {str(e)}")
        return False

if __name__ == "__main__":
    if len(sys.argv) < 3:
        print("Usage: python export_transcript.py <conversation_id> <output_path>")
    else:
        export_to_markdown(sys.argv[1], sys.argv[2])
