    exclude_dirs = {
        "node_modules", ".git", ".cache", "AppData", "Local", "Roaming", 
        "VirtualBox VMs", "Package Cache", "Microsoft", "Windows", "System32"
    }

    found = []
    try:
        for root, dirs, files in os.walk(drive_path):
            # Prune directories
            dirs[:] = [d for d in dirs if d not in exclude_dirs and not d.startswith(".")]

            for d in dirs:
                if target_name.lower() in d.lower() or target_name.lower().replace("_", "-") in d.lower() or target_name.lower().replace("-", "_") in d.lower():
