// RestartLiquidsoap forcefully terminates the Liquidsoap process so the watchdog loop restarts it
func RestartLiquidsoap() {
	name := liquidsoapName
	if name == "" {
		name = "liquidsoap.exe"
	}
	LogLocal("WARNING", "[Watchdog] Forcefully restarting Liquidsoap due to detected audio loop/skip bug...")
	_ = exec.Command("taskkill", "/F", "/IM", name).Run()
}

// GenerateLiquidsoapScript creates the player.liq script dynamically based on local configuration
func GenerateLiquidsoapScript(cfg *Config) error {
	tmpl, err := template.New("player.liq").Parse(liqTemplate)
	if err != nil {
		return err
	}

	// Ensure the parent directory of ScriptPath exists
	dir := filepath.Dir(cfg.ScriptPath)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return err
	}

	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, cfg); err != nil {
		return err
	}

	return os.WriteFile(cfg.ScriptPath, buf.Bytes(), 0644)
}

// StartLiquidsoapWatchdog runs the Liquidsoap process in a loop and restarts it if it crashes
